  add({"id": "nis6-math-010", "s": "math", "t": "ratio", "k": "ratio.divide", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Шырын мен судың қатынасы 2:3. Қоспа 35 стақан болса, су неше стақан?", "ru": "Сок и вода смешаны в отношении 2:3. Всего 35 стаканов смеси. Сколько стаканов воды?"}, "a": {"kk": "21 стақан", "ru": "21 стакан"}, "w": [[{"kk": "14 стақан", "ru": "14 стаканов"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "20 стақан", "ru": "20 стаканов"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "24 стақан", "ru": "24 стакана"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}]], "h": {"kk": "3:5 қатынасында барлығы 8 тең бөлік бар. Бір бөлікті тапқан соң керекті шаманы оның бөліктер санына көбейт.", "ru": "В отношении 3:5 всего 8 равных частей. Найди одну часть и умножь её на нужное число частей."}, "e": {"kk": "Барлығы 5 бөлік. Бір бөлік 35 ÷ 5 = 7. Су 3 × 7 = 21 стақан.", "ru": "Всего 5 частей. Одна часть 35 ÷ 5 = 7. Воды 3 × 7 = 21 стакан."}});
  add({"id": "nis6-math-011", "s": "math", "t": "ratio", "k": "ratio.scale", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Карта масштабы 1:50 000. Картадағы 4 см шындықта неше км?", "ru": "Масштаб карты 1:50 000. Сколько километров на местности соответствует 4 см на карте?"}, "a": {"kk": "2 км", "ru": "2 км"}, "w": [[{"kk": "200 м", "ru": "200 м"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "20 км", "ru": "20 км"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "0,8 км", "ru": "0,8 км"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}]], "h": {"kk": "3:5 қатынасында барлығы 8 тең бөлік бар. Бір бөлікті тапқан соң керекті шаманы оның бөліктер санына көбейт.", "ru": "В отношении 3:5 всего 8 равных частей. Найди одну часть и умножь её на нужное число частей."}, "e": {"kk": "4 × 50 000 = 200 000 см = 2 000 м = 2 км.", "ru": "4 × 50 000 = 200 000 см = 2 000 м = 2 км."}});
  add({"id": "nis6-math-012", "s": "math", "t": "ratio", "k": "ratio.divide", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Ұлдар мен қыздардың қатынасы 7:5, барлығы 36 оқушы. Ұлдар нешеу?", "ru": "Мальчики и девочки относятся как 7:5, всего 36 учеников. Сколько мальчиков?"}, "a": {"kk": "21", "ru": "21"}, "w": [[{"kk": "15", "ru": "15"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "20", "ru": "20"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "24", "ru": "24"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}]], "h": {"kk": "3:5 қатынасында барлығы 8 тең бөлік бар. Бір бөлікті тапқан соң керекті шаманы оның бөліктер санына көбейт.", "ru": "В отношении 3:5 всего 8 равных частей. Найди одну часть и умножь её на нужное число частей."}, "e": {"kk": "Барлығы 12 бөлік. Бір бөлік 36 ÷ 12 = 3. Ұлдар 7 × 3 = 21.", "ru": "Всего 12 частей. Одна часть 36 ÷ 12 = 3. Мальчиков 7 × 3 = 21."}});
  add({"id": "nis6-math-013", "s": "math", "t": "eq", "k": "eq.solve", "d": 1, "est": 60, "src": "pack1"}, {"q": {"kk": "3x + 7 = 34 теңдеуін шеш.", "ru": "Реши уравнение 3x + 7 = 34."}, "a": {"kk": "9", "ru": "9"}, "w": [[{"kk": "7", "ru": "7"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "11", "ru": "11"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "13", "ru": "13"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}]], "h": {"kk": "Теңдеудің екі жағына бірдей амал қолдан. Белгісізді жалғыз қалдыр, содан соң жауабыңды бастапқы теңдеуге қойып тексер.", "ru": "Делай одно и то же действие с обеими частями. Оставь неизвестное одно и проверь ответ подстановкой."}, "e": {"kk": "3x = 34 − 7 = 27, сондықтан x = 9.", "ru": "3x = 34 − 7 = 27, значит, x = 9."}});
  add({"id": "nis6-math-014", "s": "math", "t": "eq", "k": "eq.solve", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "4(x − 2) = 28 теңдеуін шеш.", "ru": "Реши уравнение 4(x − 2) = 28."}, "a": {"kk": "9", "ru": "9"}, "w": [[{"kk": "5", "ru": "5"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "7", "ru": "7"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "12", "ru": "12"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}]], "h": {"kk": "Теңдеудің екі жағына бірдей амал қолдан. Белгісізді жалғыз қалдыр, содан соң жауабыңды бастапқы теңдеуге қойып тексер.", "ru": "Делай одно и то же действие с обеими частями. Оставь неизвестное одно и проверь ответ подстановкой."}, "e": {"kk": "Екі жағын 4-ке бөлеміз: x − 2 = 7. Демек, x = 9.", "ru": "Делим обе части на 4: x − 2 = 7. Значит, x = 9."}});
  add({"id": "nis6-math-015", "s": "math", "t": "eq", "k": "eq.model", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Екі санның қосындысы 84, айырмасы 18. Үлкен санды тап.", "ru": "Сумма двух чисел 84, разность 18. Найди большее число."}, "a": {"kk": "51", "ru": "51"}, "w": [[{"kk": "33", "ru": "33"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "48", "ru": "48"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "57", "ru": "57"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}]], "h": {"kk": "Теңдеудің екі жағына бірдей амал қолдан. Белгісізді жалғыз қалдыр, содан соң жауабыңды бастапқы теңдеуге қойып тексер.", "ru": "Делай одно и то же действие с обеими частями. Оставь неизвестное одно и проверь ответ подстановкой."}, "e": {"kk": "Үлкен санды x десек, кішісі 84 − x. x − (84 − x) = 18, сонда 2x = 102, x = 51.", "ru": "Пусть большее число x, тогда меньшее 84 − x. x − (84 − x) = 18, 2x = 102, x = 51."}});
  add({"id": "nis6-math-016", "s": "math", "t": "eq", "k": "eq.model", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "5 бірдей дәптер мен 300 теңгелік қалам бірге 2 050 теңге тұрады. Бір дәптер қанша?", "ru": "5 одинаковых тетрадей и ручка за 300 тенге вместе стоят 2 050 тенге. Сколько стоит одна тетрадь?"}, "a": {"kk": "350 теңге", "ru": "350 тенге"}, "w": [[{"kk": "300 теңге", "ru": "300 тенге"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "400 теңге", "ru": "400 тенге"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "450 теңге", "ru": "450 тенге"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}]], "h": {"kk": "Теңдеудің екі жағына бірдей амал қолдан. Белгісізді жалғыз қалдыр, содан соң жауабыңды бастапқы теңдеуге қойып тексер.", "ru": "Делай одно и то же действие с обеими частями. Оставь неизвестное одно и проверь ответ подстановкой."}, "e": {"kk": "5 дәптердің құны 2 050 − 300 = 1 750. Біреуі 1 750 ÷ 5 = 350 теңге.", "ru": "5 тетрадей стоят 2 050 − 300 = 1 750. Одна: 1 750 ÷ 5 = 350 тенге."}});
  add({"id": "nis6-math-017", "s": "math", "t": "geo", "k": "geo.area", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Тіктөртбұрыштың периметрі 54 см, ұзындығы 16 см. Ауданын тап.", "ru": "Периметр прямоугольника 54 см, длина 16 см. Найди площадь."}, "a": {"kk": "176 см²", "ru": "176 см²"}, "w": [[{"kk": "160 см²", "ru": "160 см²"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}], [{"kk": "192 см²", "ru": "192 см²"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}], [{"kk": "216 см²", "ru": "216 см²"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}]], "h": {"kk": "Тіктөртбұрыш: P = 2(a + b), S = a × b. Үшбұрыш: S = табаны × биіктігі ÷ 2.", "ru": "Прямоугольник: P = 2(a + b), S = a × b. Треугольник: S = основание × высота ÷ 2. Куб: V = a³."}, "e": {"kk": "Ұзындық пен ен қосындысы 54 ÷ 2 = 27. Ені 11 см. Ауданы 16 × 11 = 176 см².", "ru": "Длина + ширина = 54 ÷ 2 = 27. Ширина 11 см. Площадь 16 × 11 = 176 см²."}});
  add({"id": "nis6-math-018", "s": "math", "t": "geo", "k": "geo.area", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Табаны 14 см, биіктігі 9 см үшбұрыштың ауданы қандай?", "ru": "Какова площадь треугольника с основанием 14 см и высотой 9 см?"}, "a": {"kk": "63 см²", "ru": "63 см²"}, "w": [[{"kk": "126 см²", "ru": "126 см²"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}], [{"kk": "46 см²", "ru": "46 см²"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}], [{"kk": "72 см²", "ru": "72 см²"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}]], "h": {"kk": "Тіктөртбұрыш: P = 2(a + b), S = a × b. Үшбұрыш: S = табаны × биіктігі ÷ 2.", "ru": "Прямоугольник: P = 2(a + b), S = a × b. Треугольник: S = основание × высота ÷ 2. Куб: V = a³."}, "e": {"kk": "Үшбұрыш ауданы: табан × биіктік ÷ 2 = 14 × 9 ÷ 2 = 63 см².", "ru": "Площадь треугольника: основание × высота ÷ 2 = 14 × 9 ÷ 2 = 63 см²."}});
  add({"id": "nis6-math-019", "s": "math", "t": "vol", "k": "vol.box", "d": 1, "est": 60, "src": "pack1"}, {"q": {"kk": "Қыры 5 см текшенің көлемі қандай?", "ru": "Каков объём куба с ребром 5 см?"}, "a": {"kk": "125 см³", "ru": "125 см³"}, "w": [[{"kk": "25 см³", "ru": "25 см³"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}], [{"kk": "75 см³", "ru": "75 см³"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}], [{"kk": "150 см³", "ru": "150 см³"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}]], "h": {"kk": "Тіктөртбұрыш: P = 2(a + b), S = a × b. Үшбұрыш: S = табаны × биіктігі ÷ 2.", "ru": "Прямоугольник: P = 2(a + b), S = a × b. Треугольник: S = основание × высота ÷ 2. Куб: V = a³."}, "e": {"kk": "Текше көлемі a³: 5 × 5 × 5 = 125 см³.", "ru": "Объём куба a³: 5 × 5 × 5 = 125 см³."}});
  add({"id": "nis6-math-020", "s": "math", "t": "geo", "k": "geo.area", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Шаршы қабырғасы 10 см. Қабырға 20%-ға өссе, аудан неше пайызға өседі?", "ru": "Сторона квадрата 10 см. Если сторону увеличить на 20%, на сколько процентов увеличится площадь?"}, "a": {"kk": "44%", "ru": "44%"}, "w": [[{"kk": "20%", "ru": "20%"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}], [{"kk": "40%", "ru": "40%"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}], [{"kk": "24%", "ru": "24%"}, {"kk": "Периметр мен аудан формулаларын шатастыру; аудан бірлігін квадратпен көрсету керек.", "ru": "Перепутать формулы периметра и площади; площадь записывают в квадратных единицах."}]], "h": {"kk": "Тіктөртбұрыш: P = 2(a + b), S = a × b. Үшбұрыш: S = табаны × биіктігі ÷ 2.", "ru": "Прямоугольник: P = 2(a + b), S = a × b. Треугольник: S = основание × высота ÷ 2. Куб: V = a³."}, "e": {"kk": "Жаңа қабырға 12 см. Ауданы 100-ден 144 см²-ге өседі. Өсім 44%.", "ru": "Новая сторона 12 см. Площадь растёт со 100 до 144 см². Прирост 44%."}});
  add({"id": "nis6-math-021", "s": "math", "t": "speed", "k": "speed.towards", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Аралары 210 км екі қаладан көліктер бір-біріне қарсы 60 және 80 км/сағ жылдамдықпен шықты. Қашан кездеседі?", "ru": "Из двух городов, расстояние между которыми 210 км, навстречу друг другу выехали машины со скоростями 60 и 80 км/ч. Когда они встретятся?"}, "a": {"kk": "1,5 сағаттан кейін", "ru": "через 1,5 ч"}, "w": [[{"kk": "1 сағаттан кейін", "ru": "через 1 ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "2 сағаттан кейін", "ru": "через 2 ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "2,5 сағаттан кейін", "ru": "через 2,5 ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}]], "h": {"kk": "Қашықтық = жылдамдық × уақыт. Қарсы бағыттан жақындағанда жылдамдықтарды қос.", "ru": "Расстояние = скорость × время. При движении навстречу скорости складывают. Средняя скорость = весь путь ÷ всё время."}, "e": {"kk": "Жақындасу жылдамдығы 60 + 80 = 140 км/сағ. Уақыт 210 ÷ 140 = 1,5 сағат.", "ru": "Скорость сближения 60 + 80 = 140 км/ч. Время 210 ÷ 140 = 1,5 ч."}});
  add({"id": "nis6-math-022", "s": "math", "t": "speed", "k": "speed.basic", "d": 1, "est": 60, "src": "pack1"}, {"q": {"kk": "Жаяу жүргінші 4 км/сағ жылдамдықпен 2,5 сағат жүрді. Қанша жол жүрді?", "ru": "Пешеход шёл 2,5 ч со скоростью 4 км/ч. Какое расстояние он прошёл?"}, "a": {"kk": "10 км", "ru": "10 км"}, "w": [[{"kk": "6,5 км", "ru": "6,5 км"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "8 км", "ru": "8 км"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "12 км", "ru": "12 км"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}]], "h": {"kk": "Қашықтық = жылдамдық × уақыт. Қарсы бағыттан жақындағанда жылдамдықтарды қос.", "ru": "Расстояние = скорость × время. При движении навстречу скорости складывают. Средняя скорость = весь путь ÷ всё время."}, "e": {"kk": "Қашықтық = жылдамдық × уақыт: 4 × 2,5 = 10 км.", "ru": "Расстояние = скорость × время: 4 × 2,5 = 10 км."}});
  add({"id": "nis6-math-023", "s": "math", "t": "speed", "k": "speed.basic", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Көлік 14:30-да шықты. 90 км жолды 60 км/сағ жылдамдықпен жүріп, 15 минут аялдады. Қашан келді?", "ru": "Машина выехала в 14:30. Она проехала 90 км со скоростью 60 км/ч и сделала остановку на 15 минут. Когда она приехала?"}, "a": {"kk": "16:15", "ru": "16:15"}, "w": [[{"kk": "16:00", "ru": "16:00"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "16:10", "ru": "16:10"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "16:30", "ru": "16:30"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}]], "h": {"kk": "Қашықтық = жылдамдық × уақыт. Қарсы бағыттан жақындағанда жылдамдықтарды қос.", "ru": "Расстояние = скорость × время. При движении навстречу скорости складывают. Средняя скорость = весь путь ÷ всё время."}, "e": {"kk": "90 ÷ 60 = 1,5 сағат. 14:30 + 1 сағ 30 мин = 16:00; аялдамамен 16:15.", "ru": "90 ÷ 60 = 1,5 ч. 14:30 + 1 ч 30 мин = 16:00; с остановкой — 16:15."}});
  add({"id": "nis6-math-024", "s": "math", "t": "speed", "k": "speed.average", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Велосипедші 4 км-ді 4 км/сағ, тағы 4 км-ді 8 км/сағ жүрді. Барлық жолдағы орташа жылдамдығы қандай?", "ru": "Велосипедист проехал 4 км со скоростью 4 км/ч и ещё 4 км со скоростью 8 км/ч. Какова средняя скорость на всём пути?"}, "a": {"kk": "<span class=\"fr\"><span>16</span><span>3</span></span> км/сағ", "ru": "<span class=\"fr\"><span>16</span><span>3</span></span> км/ч"}, "w": [[{"kk": "6 км/сағ", "ru": "6 км/ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "4 км/сағ", "ru": "4 км/ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "8 км/сағ", "ru": "8 км/ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}]], "h": {"kk": "Қашықтық = жылдамдық × уақыт. Қарсы бағыттан жақындағанда жылдамдықтарды қос.", "ru": "Расстояние = скорость × время. При движении навстречу скорости складывают. Средняя скорость = весь путь ÷ всё время."}, "e": {"kk": "Бірінші бөлікке 1 сағ, екіншісіне 0,5 сағ кетті. Орташа жылдамдық = 8 ÷ 1,5 = <span class=\"fr\"><span>16</span><span>3</span></span> км/сағ.", "ru": "На первую часть ушёл 1 ч, на вторую 0,5 ч. Средняя скорость = 8 ÷ 1,5 = <span class=\"fr\"><span>16</span><span>3</span></span> км/ч."}});
  add({"id": "nis6-logic-025", "s": "math", "t": "seq", "k": "seq.rule", "d": 1, "est": 60, "src": "pack1", "pool": "logic"}, {"q": {"kk": "2, 6, 12, 20, 30, … Келесі санды тап.", "ru": "2, 6, 12, 20, 30, … Найди следующее число."}, "a": {"kk": "42", "ru": "42"}, "w": [[{"kk": "40", "ru": "40"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "41", "ru": "41"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "44", "ru": "44"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}]], "h": {"kk": "Алдымен көршілес сандардың айырмасын қара. Айырмалар да заңдылық құруы мүмкін.", "ru": "Сначала посмотри на разности соседних чисел. Разности тоже могут образовывать закономерность."}, "e": {"kk": "Айырмалар 4, 6, 8, 10 болып өседі. Келесі айырма 12, сондықтан 30 + 12 = 42.", "ru": "Разности 4, 6, 8, 10 растут на 2. Следующая разность 12: 30 + 12 = 42."}});
  add({"id": "nis6-logic-026", "s": "math", "t": "seq", "k": "seq.rule", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "3, 7, 15, 31, … Келесі сан қандай?", "ru": "3, 7, 15, 31, … Какое число следующее?"}, "a": {"kk": "63", "ru": "63"}, "w": [[{"kk": "47", "ru": "47"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "60", "ru": "60"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "64", "ru": "64"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}]], "h": {"kk": "Алдымен көршілес сандардың айырмасын қара. Айырмалар да заңдылық құруы мүмкін.", "ru": "Сначала посмотри на разности соседних чисел. Разности тоже могут образовывать закономерность."}, "e": {"kk": "Әр санды 2-ге көбейтіп, 1 қосамыз: 3→7→15→31→63.", "ru": "Каждое число умножаем на 2 и прибавляем 1: 3→7→15→31→63."}});
  add({"id": "nis6-logic-027", "s": "math", "t": "seq", "k": "seq.rule", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "2, 3, 5, 8, 12, … Келесі санды тап.", "ru": "2, 3, 5, 8, 12, … Найди следующее число."}, "a": {"kk": "17", "ru": "17"}, "w": [[{"kk": "16", "ru": "16"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "18", "ru": "18"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "20", "ru": "20"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}]], "h": {"kk": "Алдымен көршілес сандардың айырмасын қара. Айырмалар да заңдылық құруы мүмкін.", "ru": "Сначала посмотри на разности соседних чисел. Разности тоже могут образовывать закономерность."}, "e": {"kk": "Айырмалар 1, 2, 3, 4. Келесі айырма 5, сондықтан 12 + 5 = 17.", "ru": "Разности 1, 2, 3, 4. Следующая разность 5: 12 + 5 = 17."}});
  add({"id": "nis6-logic-028", "s": "math", "t": "seq", "k": "seq.rule", "d": 1, "est": 60, "src": "pack1", "pool": "logic"}, {"q": {"kk": "1, 4, 9, 16, … Келесі сан қандай?", "ru": "1, 4, 9, 16, … Какое число следующее?"}, "a": {"kk": "25", "ru": "25"}, "w": [[{"kk": "20", "ru": "20"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "24", "ru": "24"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "36", "ru": "36"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}]], "h": {"kk": "Алдымен көршілес сандардың айырмасын қара. Айырмалар да заңдылық құруы мүмкін.", "ru": "Сначала посмотри на разности соседних чисел. Разности тоже могут образовывать закономерность."}, "e": {"kk": "Бұл 1², 2², 3², 4². Келесі сан 5² = 25.", "ru": "Это 1², 2², 3², 4². Следующее — 5² = 25."}});
  add({"id": "nis6-logic-029", "s": "math", "t": "logic", "k": "logic.deduce", "d": 2, "est": 120, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Айша, Бекзат және Дана жарыста 1–3-орын алды. Айша бірінші емес. Бекзат Данаға қарағанда жоғары орын алды. Дана бірінші емес. Кім бірінші?", "ru": "Айша, Бекзат и Дана заняли в соревновании места с 1-го по 3-е. Айша не первая. Бекзат занял место выше Даны. Дана не первая. Кто первый?"}, "a": {"kk": "Бекзат", "ru": "Бекзат"}, "w": [[{"kk": "Айша", "ru": "Айша"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}], [{"kk": "Дана", "ru": "Дана"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}], [{"kk": "Анықтау мүмкін емес", "ru": "Определить нельзя"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}]], "h": {"kk": "Әр кейіпкерге немесе нысанға мүмкін орындарды белгіле. Шарттарды бір-бірлеп қолдан, қайшылықтарды тексер.", "ru": "Отметь возможные места для каждого героя. Применяй условия по одному и ищи противоречия."}, "e": {"kk": "Дана бірінші емес және Бекзат одан жоғары. Айша да бірінші емес. Демек, бірінші орын Бекзаттікі.", "ru": "Дана не первая, и Бекзат выше неё. Айша тоже не первая. Значит, первое место у Бекзата."}});
  add({"id": "nis6-logic-030", "s": "math", "t": "logic", "k": "logic.deduce", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Қорапта тек қызыл немесе көк шар бар. «Шар қызыл» деген пікір жалған. Шар қандай түсті?", "ru": "В коробке только красные или синие шары. Утверждение «шар красный» ложно. Какого цвета шар?"}, "a": {"kk": "Көк", "ru": "Синий"}, "w": [[{"kk": "Қызыл", "ru": "Красный"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}], [{"kk": "Жасыл", "ru": "Зелёный"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}], [{"kk": "Анықтау мүмкін емес", "ru": "Определить нельзя"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}]], "h": {"kk": "Әр кейіпкерге немесе нысанға мүмкін орындарды белгіле. Шарттарды бір-бірлеп қолдан, қайшылықтарды тексер.", "ru": "Отметь возможные места для каждого героя. Применяй условия по одному и ищи противоречия."}, "e": {"kk": "Мүмкін түстер тек қызыл мен көк. «Қызыл» жалған болса, шар көк.", "ru": "Возможны только красный и синий. Если «красный» — ложь, шар синий."}});
  add({"id": "nis6-logic-031", "s": "math", "t": "logic", "k": "logic.deduce", "d": 3, "est": 120, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Үш кітаптың салмағы әртүрлі. A кітабы B-ден ауыр, ал C кітабы A-дан жеңіл, бірақ B-ден ауыр. Ең ауыр кітап қайсы?", "ru": "Три книги разного веса. Книга A тяжелее B, а книга C легче A, но тяжелее B. Какая книга самая тяжёлая?"}, "a": {"kk": "A кітабы", "ru": "Книга A"}, "w": [[{"kk": "B кітабы", "ru": "Книга B"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}], [{"kk": "C кітабы", "ru": "Книга C"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}], [{"kk": "Анықтау мүмкін емес", "ru": "Определить нельзя"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}]], "h": {"kk": "Әр кейіпкерге немесе нысанға мүмкін орындарды белгіле. Шарттарды бір-бірлеп қолдан, қайшылықтарды тексер.", "ru": "Отметь возможные места для каждого героя. Применяй условия по одному и ищи противоречия."}, "e": {"kk": "Берілген рет: A &gt; C &gt; B. Ең ауыры — A.", "ru": "Порядок: A &gt; C &gt; B. Самая тяжёлая — A."}});
  add({"id": "nis6-logic-032", "s": "math", "t": "data", "k": "data.read", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Команда үш ойында 12, 18 және 15 ұпай жинады. Орташа ұпайы қандай?", "ru": "Команда набрала в трёх играх 12, 18 и 15 очков. Каково среднее число очков?"}, "a": {"kk": "15", "ru": "15"}, "w": [[{"kk": "14", "ru": "14"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "16", "ru": "16"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "45", "ru": "45"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}]], "h": {"kk": "Сұрақта нақты не сұралғанын белгіле: ең көп мән, айырма, қосынды, орташа немесе өзгеріс. Қажетті сандарды ғана ал.", "ru": "Отметь, что именно спрашивают: наибольшее, разность, сумму, среднее или изменение. Бери только нужные числа."}, "e": {"kk": "Қосындысы 12 + 18 + 15 = 45. 45 ÷ 3 = 15.", "ru": "Сумма 12 + 18 + 15 = 45. 45 ÷ 3 = 15."}});
  add({"id": "nis6-logic-033", "s": "math", "t": "data", "k": "data.read", "d": 1, "est": 60, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Дүйсенбіде 24 бет, сейсенбіде 31 бет оқылды. Екінші күні қанша бет артық оқылды?", "ru": "В понедельник прочитали 24 страницы, во вторник — 31. На сколько страниц больше прочитали во второй день?"}, "a": {"kk": "7 бет", "ru": "7 страниц"}, "w": [[{"kk": "5 бет", "ru": "5 страниц"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "8 бет", "ru": "8 страниц"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "55 бет", "ru": "55 страниц"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}]], "h": {"kk": "Сұрақта нақты не сұралғанын белгіле: ең көп мән, айырма, қосынды, орташа немесе өзгеріс. Қажетті сандарды ғана ал.", "ru": "Отметь, что именно спрашивают: наибольшее, разность, сумму, среднее или изменение. Бери только нужные числа."}, "e": {"kk": "31 − 24 = 7 бет.", "ru": "31 − 24 = 7 страниц."}});
  add({"id": "nis6-logic-034", "s": "math", "t": "data", "k": "data.read", "d": 3, "est": 120, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Автобус 08:10-да шықты. Көршілес аялдамалардың арасын ол 12 минутта жүреді. Төртінші аялдамаға сағат нешеде жетеді?", "ru": "Автобус выехал в 08:10. Между соседними остановками он едет 12 минут. Во сколько он доедет до четвёртой остановки?"}, "a": {"kk": "08:58", "ru": "08:58"}, "w": [[{"kk": "08:48", "ru": "08:48"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "09:00", "ru": "09:00"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "09:10", "ru": "09:10"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}]], "h": {"kk": "Сұрақта нақты не сұралғанын белгіле: ең көп мән, айырма, қосынды, орташа немесе өзгеріс. Қажетті сандарды ғана ал.", "ru": "Отметь, что именно спрашивают: наибольшее, разность, сумму, среднее или изменение. Бери только нужные числа."}, "e": {"kk": "Төртінші аялдамаға дейін төрт аралық бар: 4 × 12 = 48 минут. 08:10 + 48 минут = 08:58.", "ru": "До четвёртой остановки четыре перегона: 4 × 12 = 48 минут. 08:10 + 48 минут = 08:58."}});
  add({"id": "nis6-logic-035", "s": "math", "t": "spatial", "k": "spatial.cube", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Кубтың барлық жақтары көк түске боялып, 3×3×3 кішкентай текшеге бөлінді. Дәл екі жағы боялған кішкентай текшелер саны қанша?", "ru": "Все грани куба покрасили в синий цвет и распилили его на 3×3×3 маленьких кубика. Сколько маленьких кубиков имеют ровно две окрашенные грани?"}, "a": {"kk": "12", "ru": "12"}, "w": [[{"kk": "8", "ru": "8"}, {"kk": "Бір қадамды өткізіп алу немесе оң мен солды шатастыру.", "ru": "Пропустить шаг или перепутать право и лево."}], [{"kk": "6", "ru": "6"}, {"kk": "Бір қадамды өткізіп алу немесе оң мен солды шатастыру.", "ru": "Пропустить шаг или перепутать право и лево."}], [{"kk": "24", "ru": "24"}, {"kk": "Бір қадамды өткізіп алу немесе оң мен солды шатастыру.", "ru": "Пропустить шаг или перепутать право и лево."}]], "h": {"kk": "Суретті елестетіп, қадамдап жүріп шық.", "ru": "Представь картинку и проходи по шагам."}, "e": {"kk": "Дәл екі жағы боялатындар — қырлардың бұрыш емес бөліктері. 12 қырдың әрқайсысында 3−2=1 текше: барлығы 12.", "ru": "Ровно две грани окрашены у кубиков на рёбрах, кроме угловых. На каждом из 12 рёбер 3 − 2 = 1 такой кубик: всего 12."}});
  add({"id": "nis6-logic-036", "s": "math", "t": "spatial", "k": "spatial.dir", "d": 1, "est": 60, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Оқушы солтүстікке қарап тұр. Ол оңға, тағы оңға, содан соң солға бұрылды. Қай бағытқа қарап тұр?", "ru": "Ученик стоит лицом на север. Он повернулся направо, ещё раз направо, затем налево. Куда он смотрит?"}, "a": {"kk": "Шығысқа", "ru": "На восток"}, "w": [[{"kk": "Батысқа", "ru": "На запад"}, {"kk": "Бір қадамды өткізіп алу немесе оң мен солды шатастыру.", "ru": "Пропустить шаг или перепутать право и лево."}], [{"kk": "Солтүстікке", "ru": "На север"}, {"kk": "Бір қадамды өткізіп алу немесе оң мен солды шатастыру.", "ru": "Пропустить шаг или перепутать право и лево."}], [{"kk": "Оңтүстікке", "ru": "На юг"}, {"kk": "Бір қадамды өткізіп алу немесе оң мен солды шатастыру.", "ru": "Пропустить шаг или перепутать право и лево."}]], "h": {"kk": "Суретті елестетіп, қадамдап жүріп шық.", "ru": "Представь картинку и проходи по шагам."}, "e": {"kk": "Солтүстік→оңға шығыс→оңға оңтүстік→солға шығыс.", "ru": "Север → направо восток → направо юг → налево восток."}});
  add({"id": "nis6-logic-037", "s": "math", "t": "prob", "k": "comb.product", "d": 1, "est": 60, "src": "pack1", "pool": "logic"}, {"q": {"kk": "3 жейде және 4 шалбардың ішінен бір жейде мен бір шалбар таңдаудың неше жолы бар?", "ru": "Сколькими способами можно выбрать одну рубашку и одни брюки из 3 рубашек и 4 брюк?"}, "a": {"kk": "12", "ru": "12"}, "w": [[{"kk": "7", "ru": "7"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}], [{"kk": "10", "ru": "10"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}], [{"kk": "24", "ru": "24"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}]], "h": {"kk": "Екі тәуелсіз таңдау болса, бірінші нұсқалардың санын екінші нұсқалардың санына көбейт. Жұпты реті маңызды емес таңдауда екі рет санап қойма.", "ru": "При двух независимых выборах число вариантов первого умножают на число вариантов второго. Если порядок не важен, не считай пару дважды."}, "e": {"kk": "Әр жейде 4 шалбардың кез келгенімен киіледі: 3 × 4 = 12.", "ru": "Каждую рубашку можно надеть с любыми из 4 брюк: 3 × 4 = 12."}});
  add({"id": "nis6-logic-038", "s": "math", "t": "prob", "k": "comb.digits", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Код екі түрлі цифрдан тұрады. 1, 2, 3 цифрларынан қайталамай неше екі таңбалы код жасауға болады?", "ru": "Код состоит из двух разных цифр. Сколько двузначных кодов без повторений можно составить из цифр 1, 2, 3?"}, "a": {"kk": "6", "ru": "6"}, "w": [[{"kk": "3", "ru": "3"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}], [{"kk": "8", "ru": "8"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}], [{"kk": "9", "ru": "9"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}]], "h": {"kk": "Екі тәуелсіз таңдау болса, бірінші нұсқалардың санын екінші нұсқалардың санына көбейт. Жұпты реті маңызды емес таңдауда екі рет санап қойма.", "ru": "При двух независимых выборах число вариантов первого умножают на число вариантов второго. Если порядок не важен, не считай пару дважды."}, "e": {"kk": "Бірінші орынға 3 таңдау, екінші орынға қалған 2 таңдау: 3 × 2 = 6.", "ru": "На первое место 3 варианта, на второе — оставшиеся 2: 3 × 2 = 6."}});
  add({"id": "nis6-logic-039", "s": "math", "t": "prob", "k": "comb.pairs", "d": 3, "est": 120, "src": "pack1", "pool": "logic"}, {"q": {"kk": "5 оқушының ішінен екі оқушыдан тұратын топты неше түрлі таңдауға болады?", "ru": "Сколькими способами можно выбрать группу из двух учеников среди 5 учеников?"}, "a": {"kk": "10", "ru": "10"}, "w": [[{"kk": "8", "ru": "8"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}], [{"kk": "12", "ru": "12"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}], [{"kk": "20", "ru": "20"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}]], "h": {"kk": "Екі тәуелсіз таңдау болса, бірінші нұсқалардың санын екінші нұсқалардың санына көбейт. Жұпты реті маңызды емес таңдауда екі рет санап қойма.", "ru": "При двух независимых выборах число вариантов первого умножают на число вариантов второго. Если порядок не важен, не считай пару дважды."}, "e": {"kk": "Жұп саны 5×4÷2 = 10. Әр жұп екі рет саналатындықтан 2-ге бөлеміз.", "ru": "Пар 5 × 4 ÷ 2 = 10. Делим на 2, потому что каждая пара посчитана дважды."}});
  add({"id": "nis6-logic-040", "s": "math", "t": "logic", "k": "logic.compare", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "x — бүтін сан. x &gt; 17 және x &lt; 21. x қандай мәндер қабылдай алады?", "ru": "x — целое число, x &gt; 17 и x &lt; 21. Какие значения может принимать x?"}, "a": {"kk": "18, 19 немесе 20", "ru": "18, 19 или 20"}, "w": [[{"kk": "17, 18, 19", "ru": "17, 18, 19"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}], [{"kk": "18 немесе 19", "ru": "18 или 19"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}], [{"kk": "Тек 20", "ru": "Только 20"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}]], "h": {"kk": "Шартқа сай келетін барлық санды тізіп шық.", "ru": "Выпиши все числа, подходящие под условие."}, "e": {"kk": "17 мен 21 арасындағы бүтін сандар: 18, 19, 20.", "ru": "Целые числа между 17 и 21: 18, 19, 20."}});
  add({"id": "nis6-logic-041", "s": "math", "t": "prob", "k": "prob.basic", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Қапта 3 қызыл, 2 көк шар бар. Кездейсоқ алынған шардың қызыл болу ықтималдығы қандай?", "ru": "В мешке 3 красных и 2 синих шара. Какова вероятность, что случайно вынутый шар красный?"}, "a": {"kk": "<span class=\"fr\"><span>3</span><span>5</span></span>", "ru": "<span class=\"fr\"><span>3</span><span>5</span></span>"}, "w": [[{"kk": "<span class=\"fr\"><span>2</span><span>5</span></span>", "ru": "<span class=\"fr\"><span>2</span><span>5</span></span>"}, {"kk": "Қолайлы нәтижелерді барлық нәтижеге емес, басқа топқа бөлу.", "ru": "Делить благоприятные исходы не на все исходы, а на другую группу."}], [{"kk": "<span class=\"fr\"><span>3</span><span>2</span></span>", "ru": "<span class=\"fr\"><span>3</span><span>2</span></span>"}, {"kk": "Қолайлы нәтижелерді барлық нәтижеге емес, басқа топқа бөлу.", "ru": "Делить благоприятные исходы не на все исходы, а на другую группу."}], [{"kk": "<span class=\"fr\"><span>1</span><span>3</span></span>", "ru": "<span class=\"fr\"><span>1</span><span>3</span></span>"}, {"kk": "Қолайлы нәтижелерді барлық нәтижеге емес, басқа топқа бөлу.", "ru": "Делить благоприятные исходы не на все исходы, а на другую группу."}]], "h": {"kk": "Ықтималдық = қолайлы нәтижелер саны : барлық нәтижелер саны.", "ru": "Вероятность = число благоприятных исходов : число всех исходов."}, "e": {"kk": "Барлығы 5 шар, оның 3-еуі қызыл. Ықтималдық <span class=\"fr\"><span>3</span><span>5</span></span>.", "ru": "Всего 5 шаров, из них 3 красных. Вероятность <span class=\"fr\"><span>3</span><span>5</span></span>."}});
  add({"id": "nis6-logic-042", "s": "math", "t": "logic", "k": "logic.compare", "d": 3, "est": 120, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Санды 5-ке бөлгенде қалдық 2, ал 3-ке бөлгенде қалдық 1. 10 мен 30 арасындағы ең кіші осындай сан қандай?", "ru": "Число при делении на 5 даёт остаток 2, а при делении на 3 — остаток 1. Какое наименьшее такое число между 10 и 30?"}, "a": {"kk": "22", "ru": "22"}, "w": [[{"kk": "17", "ru": "17"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}], [{"kk": "23", "ru": "23"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}], [{"kk": "27", "ru": "27"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}]], "h": {"kk": "Шартқа сай келетін барлық санды тізіп шық.", "ru": "Выпиши все числа, подходящие под условие."}, "e": {"kk": "10–30 аралығындағы 5-ке бөлгенде 2 қалдық беретін сандар: 12,17,22,27. 22-ні 3-ке бөлгенде 1 қалдық қалады.", "ru": "Числа от 10 до 30 с остатком 2 при делении на 5: 12, 17, 22, 27. Из них остаток 1 при делении на 3 даёт 22."}});
