  add({"id": "nis6-english-051", "s": "en", "t": "enmini", "k": "en.read", "d": 1, "est": 60, "src": "pack1", "lv": 1}, {"fixed": "en", "q": "Read: “The library opens at 9:00 on Saturday and closes at 2:00.” When does it close?", "a": "At 2:00", "w": [["At 9:00", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["At 12:00", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["At 5:00", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}]], "h": {"kk": "Алдымен сұрақты оқы. Мәтіндегі тірек сөзді тап.", "ru": "Сначала прочитай вопрос. Найди в тексте ключевое слово. Проверь, что текст подтверждает ответ."}, "e": {"kk": "Мәтінде жабылу уақыты тікелей 2:00 деп берілген.", "ru": "В тексте прямо сказано, что библиотека закрывается в 2:00."}});
  add({"id": "nis6-english-052", "s": "en", "t": "enmini", "k": "en.grammar", "d": 1, "est": 60, "src": "pack1", "lv": 1}, {"fixed": "en", "q": "___ you swim? — Yes, I can.", "a": "Can", "w": [["Do", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["Are", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["Have", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}]], "h": {"kk": "Әдеттегі іс үшін Present Simple; yesterday сияқты өткен уақыт белгісімен Past Simple. He/she/it тұлғасында етістікке -s/-es жалғанады.", "ru": "Present Simple — для привычных действий; с yesterday — Past Simple. С he/she/it к глаголу добавляется -s/-es."}, "e": {"kk": "«Yes, I can» жауабы қабілет туралы сұралып тұрғанын көрсетеді: Can you swim?", "ru": "Ответ «Yes, I can» показывает, что спрашивают об умении: Can you swim?"}});
  add({"id": "nis6-english-053", "s": "en", "t": "enmini", "k": "en.grammar", "d": 2, "est": 120, "src": "pack1", "lv": 2}, {"fixed": "en", "q": "There isn’t ___ milk in the fridge.", "a": "any", "w": [["some", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["many", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["a few", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}]], "h": {"kk": "Әдеттегі іс үшін Present Simple; yesterday сияқты өткен уақыт белгісімен Past Simple. He/she/it тұлғасында етістікке -s/-es жалғанады.", "ru": "Present Simple — для привычных действий; с yesterday — Past Simple. С he/she/it к глаголу добавляется -s/-es."}, "e": {"kk": "Болымсыз сөйлемдерде саналмайтын milk сөзімен any қолданылады.", "ru": "В отрицаниях с неисчисляемым milk используется any."}});
  add({"id": "nis6-english-054", "s": "en", "t": "enmini", "k": "en.read", "d": 3, "est": 120, "src": "pack1", "lv": 3}, {"fixed": "en", "q": "Read: “Tim put on his coat, zipped it up, and took an umbrella before leaving.” What is most likely true?", "a": "The weather may be cold or rainy.", "w": [["Tim is going swimming.", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["It is definitely sunny.", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["Tim is staying at home.", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}]], "h": {"kk": "Алдымен сұрақты оқы. Мәтіндегі тірек сөзді тап.", "ru": "Сначала прочитай вопрос. Найди в тексте ключевое слово. Проверь, что текст подтверждает ответ."}, "e": {"kk": "Пальто мен қолшатыр ауа райының суық не жаңбырлы болуы мүмкін екенін аңғартады, бірақ нақты ауа райы айтылмаған.", "ru": "Пальто и зонт подсказывают, что погода может быть холодной или дождливой, но точная погода не названа."}});
  add({"id": "nis6-science-055", "s": "sci", "t": "sexp", "k": "sci.method", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Өсімдік өсуіне жарықтың әсерін тексеруде екі бірдей өсімдікке су мен топырақ бірдей беріледі, тек біреуіне жарық түседі. Қай шама әдейі өзгертіледі?", "ru": "Проверяют влияние света на рост растения: двум одинаковым растениям дают одинаково воды и почвы, но свет падает только на одно. Какое условие меняют намеренно?"}, "a": {"kk": "Жарық мөлшері", "ru": "Количество света"}, "w": [[{"kk": "Су мөлшері", "ru": "Количество воды"}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}], [{"kk": "Топырақ түрі", "ru": "Тип почвы"}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}], [{"kk": "Өсімдік саны", "ru": "Число растений"}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}]], "h": {"kk": "Бір ғана факторды әдейі өзгерт. Қалған маңызды шарттарды бірдей ұста.", "ru": "Намеренно меняй только один фактор. Остальные важные условия держи одинаковыми. Вывод делай только по данным."}, "e": {"kk": "Әділ тәжірибеде бір ғана шартты әдейі өзгертеді. Бұл жерде ол — жарық мөлшері.", "ru": "В честном опыте намеренно меняют только одно условие. Здесь это количество света."}});
  add({"id": "nis6-science-056", "s": "sci", "t": "sexp", "k": "sci.method", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Тәжірибеде тұз жылы суда суық суға қарағанда тез еріді. Қай қорытынды дерекке сай?", "ru": "В опыте соль растворилась в тёплой воде быстрее, чем в холодной. Какой вывод соответствует данным?"}, "a": {"kk": "Осы жағдайда температура артқанда тұз тезірек еріді.", "ru": "В этих условиях при повышении температуры соль растворялась быстрее."}, "w": [[{"kk": "Тұз тек жылы суда ериді.", "ru": "Соль растворяется только в тёплой воде."}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}], [{"kk": "Судың мөлшері әсер етпейді.", "ru": "Количество воды не влияет."}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}], [{"kk": "Тұз жоғалып кетті.", "ru": "Соль исчезла."}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}]], "h": {"kk": "Бір ғана факторды әдейі өзгерт. Қалған маңызды шарттарды бірдей ұста.", "ru": "Намеренно меняй только один фактор. Остальные важные условия держи одинаковыми. Вывод делай только по данным."}, "e": {"kk": "Бақылау тек берілген екі жағдайдағы еру жылдамдығын салыстыруға мүмкіндік береді; артық қорытынды жасауға болмайды.", "ru": "Наблюдение позволяет сравнить только скорость растворения в двух данных случаях; лишних выводов делать нельзя."}});
  add({"id": "nis6-science-057", "s": "sci", "t": "schem", "k": "sci.mixtures", "d": 1, "est": 60, "src": "pack1"}, {"q": {"kk": "Қант суға араласқанда қант түйірлері көрінбей кетті. Қай сипаттама дұрыс?", "ru": "Когда сахар размешали в воде, крупинки сахара перестали быть видны. Какое описание верно?"}, "a": {"kk": "Қант суда еріп, ерітінді түзді.", "ru": "Сахар растворился в воде и образовал раствор."}, "w": [[{"kk": "Қант буланып кетті.", "ru": "Сахар испарился."}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}], [{"kk": "Қант жаңа газға айналды.", "ru": "Сахар превратился в новый газ."}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}], [{"kk": "Су қатты затқа айналды.", "ru": "Вода превратилась в твёрдое вещество."}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}]], "h": {"kk": "Құбылыстың себебі мен нәтижесін ажырат.", "ru": "Отдели причину явления от результата."}, "e": {"kk": "Қант бөлшектері суда таралады. Көрінбей кетуі оның жоғалғанын білдірмейді.", "ru": "Частицы сахара распределились в воде. То, что их не видно, не значит, что сахар исчез."}});
  add({"id": "nis6-science-058", "s": "sci", "t": "sgeo", "k": "sci.earth", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Күн ашық күні талдың көлеңкесі таңертең ұзын, түсте қысқа болды. Ең дұрыс түсіндіру қандай?", "ru": "В ясный день тень дерева утром была длинной, а в полдень — короткой. Какое объяснение самое верное?"}, "a": {"kk": "Күннің аспандағы көрінерлік орны өзгерді.", "ru": "Изменилось видимое положение Солнца на небе."}, "w": [[{"kk": "Талдың биіктігі түсте азайды.", "ru": "В полдень дерево стало ниже."}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}], [{"kk": "Жер Күнге жақындап кетті.", "ru": "Земля приблизилась к Солнцу."}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}], [{"kk": "Көлеңке өздігінен қозғалды.", "ru": "Тень сдвинулась сама."}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}]], "h": {"kk": "Құбылыстың себебі мен нәтижесін ажырат.", "ru": "Отдели причину явления от результата."}, "e": {"kk": "Күннің аспандағы көрінерлік орны өзгерген сайын жарық түсу бағыты және көлеңке ұзындығы өзгереді.", "ru": "Когда меняется видимое положение Солнца на небе, меняются направление лучей и длина тени."}});
  add({"id": "nis6-science-059", "s": "sci", "t": "sbio", "k": "sci.ecology", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Шөп → қоян → түлкі тізбегінде қоян қандай рөл атқарады?", "ru": "Какую роль в цепи трава → заяц → лиса играет заяц?"}, "a": {"kk": "Шөппен қоректенетін тұтынушы", "ru": "Растительноядный потребитель"}, "w": [[{"kk": "Өндіруші", "ru": "Производитель"}, {"kk": "Жебені «кім кімді жейді» бағытымен шатастыру; жебе энергияның берілу бағытын көрсетеді.", "ru": "Перепутать направление стрелки: она показывает, куда передаётся энергия."}], [{"kk": "Ыдыратушы", "ru": "Разрушитель"}, {"kk": "Жебені «кім кімді жейді» бағытымен шатастыру; жебе энергияның берілу бағытын көрсетеді.", "ru": "Перепутать направление стрелки: она показывает, куда передаётся энергия."}], [{"kk": "Күн энергиясының көзі", "ru": "Источник солнечной энергии"}, {"kk": "Жебені «кім кімді жейді» бағытымен шатастыру; жебе энергияның берілу бағытын көрсетеді.", "ru": "Перепутать направление стрелки: она показывает, куда передаётся энергия."}]], "h": {"kk": "Өсімдіктер күн энергиясын пайдаланып органикалық зат түзеді. Жануарлар басқа ағзалармен қоректенетін тұтынушылар.", "ru": "Растения создают органические вещества за счёт энергии Солнца. Животные — потребители. Стрелка показывает передачу энергии."}, "e": {"kk": "Қоян өсімдікті жейтіндіктен бірінші реттік тұтынушы болады.", "ru": "Заяц питается растениями, поэтому он — потребитель первого порядка."}});
  add({"id": "nis6-science-060", "s": "sci", "t": "sphys", "k": "sci.heat", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Металл қасықтың бір ұшын ыстық шайға салғанда, сабы да қыза бастады. Жылу негізінен қалай берілді?", "ru": "Один конец металлической ложки опустили в горячий чай, и её ручка тоже начала нагреваться. Как в основном передалось тепло?"}, "a": {"kk": "Қасық бойымен жылу өткізгіштік арқылы", "ru": "Теплопроводностью вдоль ложки"}, "w": [[{"kk": "Дыбыс толқыны арқылы", "ru": "Звуковой волной"}, {"kk": "Бақыланған өзгерістен артық қорытынды жасау.", "ru": "Делать слишком широкий вывод из одного наблюдения."}], [{"kk": "Булану арқылы ғана", "ru": "Только испарением"}, {"kk": "Бақыланған өзгерістен артық қорытынды жасау.", "ru": "Делать слишком широкий вывод из одного наблюдения."}], [{"kk": "Магниттік тартылыс арқылы", "ru": "Магнитным притяжением"}, {"kk": "Бақыланған өзгерістен артық қорытынды жасау.", "ru": "Делать слишком широкий вывод из одного наблюдения."}]], "h": {"kk": "Жылу жылырақ денеден салқынырақ денеге беріледі. Металл жылуды жақсы өткізеді.", "ru": "Тепло передаётся от более тёплого тела к более холодному. Металл хорошо проводит тепло."}, "e": {"kk": "Қатты металда бөлшектер арасындағы энергия алмасу жылуды қасық бойымен таратады.", "ru": "В твёрдом металле энергия передаётся между частицами, и тепло распространяется вдоль ложки."}});
  add({"id": "nis6-kk-061", "s": "kk", "t": "kkmini", "k": "kk.read", "d": 2, "est": 90, "src": "pack1"}, {"fixed": "kk", "q": "Мәтін: «Мектеп ауласында оқушылар ағаш отырғызды. Әр сынып бір көшетті күтіп-баптауға жауапты болды. Күзде ағаштардың көбі жақсы өсті». Мәтіннің негізгі ойы қандай?", "a": "Бірлескен күтім көшеттердің өсуіне көмектесті.", "w": [["Күзде мектепте сабақ болмады.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."], ["Ағашты тек мұғалімдер отырғызды.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."], ["Көшеттердің бәрі қурап қалды.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."]], "h": "Негізгі ой бірнеше сөйлемді біріктіреді. Тікелей дерек мәтінде нақты айтылады.", "e": "Мәтіннің басы мен соңы оқушылардың күтімі мен ағаштардың өсуін байланыстырады."});
  add({"id": "nis6-kk-062", "s": "kk", "t": "kkmini", "k": "kk.grammar", "d": 1, "est": 60, "src": "pack1"}, {"fixed": "kk", "q": "«Оқушылар жаңа кітапты мұқият оқыды» сөйлеміндегі қимылды білдіретін сөзді тап.", "a": "оқыды", "w": [["оқушылар", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."], ["жаңа", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."], ["мұқият", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."]], "h": "Сөзге сұрақ қойып көр: кім? не істеді? қалай?", "e": "Оқыды сөзі не істеді? деген сұраққа жауап береді, қимылды білдіреді."});
  add({"id": "nis6-kk-063", "s": "kk", "t": "kkmini", "k": "kk.read", "d": 3, "est": 120, "src": "pack1"}, {"fixed": "kk", "q": "Мәтін: «Аружан терезені жауып, жылы жемпір киді. Далада ағаш бұтақтары қозғалып тұрды». Мәтіннен тікелей анықталатын тұжырымды таңда.", "a": "Аружан жылы киім киді.", "w": [["Сыртта қар жауып тұр.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."], ["Аружан ауырып қалды.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."], ["Желдің жылдамдығы 20 км/сағ.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."]], "h": "Негізгі ой бірнеше сөйлемді біріктіреді. Тікелей дерек мәтінде нақты айтылады.", "e": "Мәтінде жемпір кигені нақты айтылған. Қар, ауру және жел жылдамдығы туралы дерек жоқ."});
  add({"id": "nis6-ru-064", "s": "ru", "t": "rumini", "k": "ru.read", "d": 2, "est": 90, "src": "pack1"}, {"fixed": "ru", "q": "Текст: «Класс договорился приносить макулатуру каждую пятницу. За месяц ребята собрали бумагу и отправили её на переработку». Какова главная мысль?", "a": "Совместное действие помогло собрать бумагу для переработки.", "w": [["Класс отменил занятия по пятницам.", "Принять то, что знаешь сам, за факт из текста."], ["Ребята печатали новые книги.", "Принять то, что знаешь сам, за факт из текста."], ["Макулатуру собирали только учителя.", "Принять то, что знаешь сам, за факт из текста."]], "h": "Главная мысль объединяет несколько предложений. Факт прямо сказан в тексте; предположение текст может не подтверждать.", "e": "Оба предложения описывают общее действие класса и его цель — переработку бумаги."});
  add({"id": "nis6-ru-065", "s": "ru", "t": "rumini", "k": "ru.grammar", "d": 1, "est": 60, "src": "pack1"}, {"fixed": "ru", "q": "В предложении «Девочка быстро решила задачу» какое слово обозначает действие?", "a": "решила", "w": [["девочка", "Не задать вопрос и перепутать часть речи или форму слова."], ["быстро", "Не задать вопрос и перепутать часть речи или форму слова."], ["задачу", "Не задать вопрос и перепутать часть речи или форму слова."]], "h": "Задай к слову вопрос: что сделал? какая?", "e": "Решила отвечает на вопрос «что сделала?» и обозначает действие."});
  add({"id": "nis6-ru-066", "s": "ru", "t": "rumini", "k": "ru.read", "d": 3, "est": 120, "src": "pack1"}, {"fixed": "ru", "q": "Текст: «На улице асфальт мокрый, а у двери стоят раскрытые зонты». Что можно утверждать по тексту?", "a": "Асфальт мокрый.", "w": [["Дождь закончился ровно пять минут назад.", "Принять то, что знаешь сам, за факт из текста."], ["Все люди промокли.", "Принять то, что знаешь сам, за факт из текста."], ["На улице холодно.", "Принять то, что знаешь сам, за факт из текста."]], "h": "Главная мысль объединяет несколько предложений. Факт прямо сказан в тексте; предположение текст может не подтверждать.", "e": "Мокрый асфальт прямо назван в тексте. Остальные варианты — предположения, которых текст не подтверждает."});
  add({"id": "nis6-math-067", "s": "math", "t": "frac", "k": "frac.ops", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "2 <span class=\"fr\"><span>1</span><span>4</span></span> − <span class=\"fr\"><span>5</span><span>6</span></span> мәнін тап.", "ru": "Найди значение 2 <span class=\"fr\"><span>1</span><span>4</span></span> − <span class=\"fr\"><span>5</span><span>6</span></span>."}, "a": {"kk": "1 <span class=\"fr\"><span>5</span><span>12</span></span>", "ru": "1 <span class=\"fr\"><span>5</span><span>12</span></span>"}, "w": [[{"kk": "1 <span class=\"fr\"><span>7</span><span>12</span></span>", "ru": "1 <span class=\"fr\"><span>7</span><span>12</span></span>"}, {"kk": "Алым мен бөлімді жеке-жеке қосу немесе азайту. Алдымен ортақ бөлім тап.", "ru": "Складывать или вычитать числители и знаменатели по отдельности. Сначала найди общий знаменатель."}], [{"kk": "1 <span class=\"fr\"><span>1</span><span>3</span></span>", "ru": "1 <span class=\"fr\"><span>1</span><span>3</span></span>"}, {"kk": "Алым мен бөлімді жеке-жеке қосу немесе азайту. Алдымен ортақ бөлім тап.", "ru": "Складывать или вычитать числители и знаменатели по отдельности. Сначала найди общий знаменатель."}], [{"kk": "2 <span class=\"fr\"><span>1</span><span>12</span></span>", "ru": "2 <span class=\"fr\"><span>1</span><span>12</span></span>"}, {"kk": "Алым мен бөлімді жеке-жеке қосу немесе азайту. Алдымен ортақ бөлім тап.", "ru": "Складывать или вычитать числители и знаменатели по отдельности. Сначала найди общий знаменатель."}]], "h": {"kk": "Бөлшектің алымы алынған бөліктерді, бөлімі бүтіннің тең бөліктер санын көрсетеді. Қосу мен азайтуда бөлімдерді ортақ ету керек.", "ru": "Числитель показывает взятые части, знаменатель — на сколько равных частей делят целое. При сложении и вычитании нужен общий знаменатель."}, "e": {"kk": "Ортақ бөлім 12: 2 <span class=\"fr\"><span>1</span><span>4</span></span> = <span class=\"fr\"><span>27</span><span>12</span></span>, <span class=\"fr\"><span>5</span><span>6</span></span> = <span class=\"fr\"><span>10</span><span>12</span></span>. Айырымы <span class=\"fr\"><span>17</span><span>12</span></span> = 1 <span class=\"fr\"><span>5</span><span>12</span></span>.", "ru": "Общий знаменатель 12: 2 <span class=\"fr\"><span>1</span><span>4</span></span> = <span class=\"fr\"><span>27</span><span>12</span></span>, <span class=\"fr\"><span>5</span><span>6</span></span> = <span class=\"fr\"><span>10</span><span>12</span></span>. Разность <span class=\"fr\"><span>17</span><span>12</span></span> = 1 <span class=\"fr\"><span>5</span><span>12</span></span>."}});
  add({"id": "nis6-math-068", "s": "math", "t": "pct", "k": "pct.find", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "480 санының 35%-ын тап.", "ru": "Найди 35% от числа 480."}, "a": {"kk": "168", "ru": "168"}, "w": [[{"kk": "148", "ru": "148"}, {"kk": "Пайызды жаңа бағаға емес, бастапқы бағаға қатысты есептеу керегін ұмыту.", "ru": "Забыть, что процент считают от начальной, а не от новой цены."}], [{"kk": "158", "ru": "158"}, {"kk": "Пайызды жаңа бағаға емес, бастапқы бағаға қатысты есептеу керегін ұмыту.", "ru": "Забыть, что процент считают от начальной, а не от новой цены."}], [{"kk": "175", "ru": "175"}, {"kk": "Пайызды жаңа бағаға емес, бастапқы бағаға қатысты есептеу керегін ұмыту.", "ru": "Забыть, что процент считают от начальной, а не от новой цены."}]], "h": {"kk": "1% = 1/100. Пайыздық өсім не кему бастапқы мәннен есептеледі.", "ru": "1% = 1/100. Процентное увеличение или уменьшение считают от начального значения. При скидке 20% остаётся 80% цены."}, "e": {"kk": "30%-ы 144, 5%-ы 24. Қосындысы 168.", "ru": "30% — это 144, 5% — это 24. Вместе 168."}});
  add({"id": "nis6-math-069", "s": "math", "t": "ratio", "k": "ratio.simplify", "d": 1, "est": 60, "src": "pack1"}, {"q": {"kk": "18:24 қатынасын ең қарапайым түрге келтір.", "ru": "Приведи отношение 18:24 к простейшему виду."}, "a": {"kk": "3:4", "ru": "3:4"}, "w": [[{"kk": "2:3", "ru": "2:3"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "6:8", "ru": "6:8"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "4:3", "ru": "4:3"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}]], "h": {"kk": "3:5 қатынасында барлығы 8 тең бөлік бар. Бір бөлікті тапқан соң керекті шаманы оның бөліктер санына көбейт.", "ru": "В отношении 3:5 всего 8 равных частей. Найди одну часть и умножь её на нужное число частей."}, "e": {"kk": "18 бен 24-ті ең үлкен ортақ бөлгіш 6-ға бөлеміз: 3:4.", "ru": "Делим 18 и 24 на их НОД 6: 3:4."}});
  add({"id": "nis6-math-070", "s": "math", "t": "ratio", "k": "ratio.scale", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Масштабы 1:25 000 картада жол 7,2 см. Нақты қашықтық неше км?", "ru": "На карте масштаба 1:25 000 дорога имеет длину 7,2 см. Каково расстояние на местности в км?"}, "a": {"kk": "1,8 км", "ru": "1,8 км"}, "w": [[{"kk": "18 км", "ru": "18 км"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "0,18 км", "ru": "0,18 км"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "2,5 км", "ru": "2,5 км"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}]], "h": {"kk": "3:5 қатынасында барлығы 8 тең бөлік бар. Бір бөлікті тапқан соң керекті шаманы оның бөліктер санына көбейт.", "ru": "В отношении 3:5 всего 8 равных частей. Найди одну часть и умножь её на нужное число частей."}, "e": {"kk": "7,2 × 25 000 = 180 000 см = 1 800 м = 1,8 км.", "ru": "7,2 × 25 000 = 180 000 см = 1 800 м = 1,8 км."}});
  add({"id": "nis6-math-071", "s": "math", "t": "eq", "k": "eq.solve", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "2(3x + 1) = 38 теңдеуін шеш.", "ru": "Реши уравнение 2(3x + 1) = 38."}, "a": {"kk": "6", "ru": "6"}, "w": [[{"kk": "5", "ru": "5"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "7", "ru": "7"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}], [{"kk": "12", "ru": "12"}, {"kk": "Амалдың ретін сақтамау немесе теңдеудің тек бір жағын өзгерту.", "ru": "Нарушить порядок действий или изменить только одну часть уравнения."}]], "h": {"kk": "Теңдеудің екі жағына бірдей амал қолдан. Белгісізді жалғыз қалдыр, содан соң жауабыңды бастапқы теңдеуге қойып тексер.", "ru": "Делай одно и то же действие с обеими частями. Оставь неизвестное одно и проверь ответ подстановкой."}, "e": {"kk": "Екі жағын 2-ге бөлеміз: 3x+1=19. 3x=18, сондықтан x=6.", "ru": "Делим обе части на 2: 3x + 1 = 19. 3x = 18, значит, x = 6."}});
