  add({"id": "nis6-math-076", "s": "math", "t": "speed", "k": "speed.basic", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "72 км жолды 48 км/сағ жылдамдықпен жүруге қанша уақыт кетеді?", "ru": "Сколько времени нужно, чтобы проехать 72 км со скоростью 48 км/ч?"}, "a": {"kk": "1,5 сағат", "ru": "1,5 ч"}, "w": [[{"kk": "1 сағат", "ru": "1 ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "2 сағат", "ru": "2 ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "2,5 сағат", "ru": "2,5 ч"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}]], "h": {"kk": "Қашықтық = жылдамдық × уақыт. Қарсы бағыттан жақындағанда жылдамдықтарды қос.", "ru": "Расстояние = скорость × время. При движении навстречу скорости складывают. Средняя скорость = весь путь ÷ всё время."}, "e": {"kk": "Уақыт = қашықтық ÷ жылдамдық = 72 ÷ 48 = 1,5 сағат.", "ru": "Время = расстояние ÷ скорость = 72 ÷ 48 = 1,5 ч."}});
  add({"id": "nis6-math-077", "s": "math", "t": "speed", "k": "speed.catchup", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Екі көлік бір жерден бір бағытта шықты. Жылдамдықтары 70 және 55 км/сағ. 2 сағаттан кейін аралары қанша болады?", "ru": "Две машины выехали из одного места в одном направлении со скоростями 70 и 55 км/ч. Какое расстояние будет между ними через 2 часа?"}, "a": {"kk": "30 км", "ru": "30 км"}, "w": [[{"kk": "15 км", "ru": "15 км"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "25 км", "ru": "25 км"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}], [{"kk": "140 км", "ru": "140 км"}, {"kk": "Орташа жылдамдықты екі жылдамдықтың арифметикалық ортасымен шатастыру.", "ru": "Считать среднюю скорость как среднее двух скоростей."}]], "h": {"kk": "Қашықтық = жылдамдық × уақыт. Қарсы бағыттан жақындағанда жылдамдықтарды қос.", "ru": "Расстояние = скорость × время. При движении навстречу скорости складывают. Средняя скорость = весь путь ÷ всё время."}, "e": {"kk": "Ара қашықтық айырмасы бойынша өседі: (70−55)×2 = 30 км.", "ru": "Расстояние растёт на разность скоростей: (70 − 55) × 2 = 30 км."}});
  add({"id": "nis6-math-078", "s": "math", "t": "ratio", "k": "ratio.divide", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Қоспада шырын мен судың қатынасы 4:1. Қоспа 45 л болса, шырын неше литр?", "ru": "В смеси сок и вода относятся как 4:1. Смеси 45 л. Сколько литров сока?"}, "a": {"kk": "36 л", "ru": "36 л"}, "w": [[{"kk": "9 л", "ru": "9 л"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "32 л", "ru": "32 л"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}], [{"kk": "40 л", "ru": "40 л"}, {"kk": "Қатынастағы сандарды нақты зат саны деп қабылдау; олар тең үлестердің санын білдіреді.", "ru": "Принять числа отношения за количество предметов; они показывают число равных долей."}]], "h": {"kk": "3:5 қатынасында барлығы 8 тең бөлік бар. Бір бөлікті тапқан соң керекті шаманы оның бөліктер санына көбейт.", "ru": "В отношении 3:5 всего 8 равных частей. Найди одну часть и умножь её на нужное число частей."}, "e": {"kk": "Барлығы 5 бөлік, бір бөлік 45÷5=9 л. Шырын 4×9=36 л.", "ru": "Всего 5 частей, одна часть 45 ÷ 5 = 9 л. Сока 4 × 9 = 36 л."}});
  add({"id": "nis6-logic-079", "s": "math", "t": "seq", "k": "seq.rule", "d": 3, "est": 120, "src": "pack1", "pool": "logic"}, {"q": {"kk": "4, 10, 22, 46, … Келесі санды тап.", "ru": "4, 10, 22, 46, … Найди следующее число."}, "a": {"kk": "94", "ru": "94"}, "w": [[{"kk": "88", "ru": "88"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "90", "ru": "90"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "96", "ru": "96"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}]], "h": {"kk": "Алдымен көршілес сандардың айырмасын қара. Айырмалар да заңдылық құруы мүмкін.", "ru": "Сначала посмотри на разности соседних чисел. Разности тоже могут образовывать закономерность."}, "e": {"kk": "Әр мүшені 2-ге көбейтіп, 2 қосамыз: 4→10→22→46→94.", "ru": "Каждый член умножаем на 2 и прибавляем 2: 4→10→22→46→94."}});
  add({"id": "nis6-logic-080", "s": "math", "t": "seq", "k": "seq.rule", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "1, 3, 6, 10, 15, … Келесі сан қандай?", "ru": "1, 3, 6, 10, 15, … Какое число следующее?"}, "a": {"kk": "21", "ru": "21"}, "w": [[{"kk": "20", "ru": "20"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "22", "ru": "22"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "25", "ru": "25"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}]], "h": {"kk": "Алдымен көршілес сандардың айырмасын қара. Айырмалар да заңдылық құруы мүмкін.", "ru": "Сначала посмотри на разности соседних чисел. Разности тоже могут образовывать закономерность."}, "e": {"kk": "Қосылатын сандар 2, 3, 4, 5. Келесіде 6 қосылады: 15+6=21.", "ru": "Прибавляются 2, 3, 4, 5. Дальше прибавляем 6: 15 + 6 = 21."}});
  add({"id": "nis6-logic-081", "s": "math", "t": "seq", "k": "seq.rule", "d": 1, "est": 60, "src": "pack1", "pool": "logic"}, {"q": {"kk": "5, 10, 20, 40, … Келесі санды тап.", "ru": "5, 10, 20, 40, … Найди следующее число."}, "a": {"kk": "80", "ru": "80"}, "w": [[{"kk": "60", "ru": "60"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "70", "ru": "70"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}], [{"kk": "100", "ru": "100"}, {"kk": "Алғаш көрінген ережені тексермей қабылдау. Ережені қатардың барлық мүшесіне қолданып көр.", "ru": "Принять первое замеченное правило без проверки. Проверь правило на всех членах ряда."}]], "h": {"kk": "Алдымен көршілес сандардың айырмасын қара. Айырмалар да заңдылық құруы мүмкін.", "ru": "Сначала посмотри на разности соседних чисел. Разности тоже могут образовывать закономерность."}, "e": {"kk": "Әр сан алдыңғы саннан 2 есе үлкен: 40 × 2 = 80.", "ru": "Каждое число в 2 раза больше предыдущего: 40 × 2 = 80."}});
  add({"id": "nis6-logic-082", "s": "math", "t": "logic", "k": "logic.deduce", "d": 3, "est": 120, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Айдана жаттығуды дүйсенбі, сәрсенбі немесе жұмада жасайды. Ол жұмада жасамайды. Сәрсенбіде сабақ бар, ал жаттығу сабақ жоқ күні өтеді. Жаттығу қай күні?", "ru": "Айдана тренируется в понедельник, среду или пятницу. В пятницу она не тренируется. В среду у неё уроки, а тренировка бывает только в день без уроков. В какой день тренировка?"}, "a": {"kk": "Дүйсенбіде", "ru": "В понедельник"}, "w": [[{"kk": "Сәрсенбіде", "ru": "В среду"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}], [{"kk": "Жұмада", "ru": "В пятницу"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}], [{"kk": "Анықтау мүмкін емес", "ru": "Определить нельзя"}, {"kk": "Шарттың біреуін ұмытып кету немесе «төмен» сөзін орын ретін дұрыс түсінбеу.", "ru": "Забыть одно из условий или неверно понять слова «выше/ниже»."}]], "h": {"kk": "Әр кейіпкерге немесе нысанға мүмкін орындарды белгіле. Шарттарды бір-бірлеп қолдан, қайшылықтарды тексер.", "ru": "Отметь возможные места для каждого героя. Применяй условия по одному и ищи противоречия."}, "e": {"kk": "Жұма жоққа шығарылды, сәрсенбіде сабақ бар. Қалған жалғыз күн — дүйсенбі.", "ru": "Пятница исключена, в среду уроки. Остаётся только понедельник."}});
  add({"id": "nis6-logic-083", "s": "math", "t": "data", "k": "data.read", "d": 1, "est": 60, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Төрт күнде оқылған беттер: 18, 24, 21, 27. Ең көп және ең аз мәннің айырмасы қанша?", "ru": "За четыре дня прочитали 18, 24, 21 и 27 страниц. Какова разность наибольшего и наименьшего значений?"}, "a": {"kk": "9 бет", "ru": "9 страниц"}, "w": [[{"kk": "6 бет", "ru": "6 страниц"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "8 бет", "ru": "8 страниц"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "12 бет", "ru": "12 страниц"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}]], "h": {"kk": "Сұрақта нақты не сұралғанын белгіле: ең көп мән, айырма, қосынды, орташа немесе өзгеріс. Қажетті сандарды ғана ал.", "ru": "Отметь, что именно спрашивают: наибольшее, разность, сумму, среднее или изменение. Бери только нужные числа."}, "e": {"kk": "Ең көбі 27, ең азы 18. Айырмасы 27−18=9.", "ru": "Наибольшее 27, наименьшее 18. Разность 27 − 18 = 9."}});
  add({"id": "nis6-logic-084", "s": "math", "t": "data", "k": "data.read", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Үш күннің орташа температурасы 16°C. Алғашқы екі күн 14°C және 19°C болды. Үшінші күн қандай?", "ru": "Средняя температура трёх дней 16°C. Первые два дня было 14°C и 19°C. Какая температура была на третий день?"}, "a": {"kk": "15°C", "ru": "15°C"}, "w": [[{"kk": "14°C", "ru": "14°C"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "16°C", "ru": "16°C"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}], [{"kk": "17°C", "ru": "17°C"}, {"kk": "Кестедегі барлық санды есепке алу; тек сұраққа қатысты жолдар мен бағандарды қолдан.", "ru": "Использовать все числа подряд; бери только строки и столбцы, относящиеся к вопросу."}]], "h": {"kk": "Сұрақта нақты не сұралғанын белгіле: ең көп мән, айырма, қосынды, орташа немесе өзгеріс. Қажетті сандарды ғана ал.", "ru": "Отметь, что именно спрашивают: наибольшее, разность, сумму, среднее или изменение. Бери только нужные числа."}, "e": {"kk": "Үш күннің қосындысы 3×16=48. Үшінші күн: 48−14−19=15°C.", "ru": "Сумма за три дня 3 × 16 = 48. Третий день: 48 − 14 − 19 = 15°C."}});
  add({"id": "nis6-logic-086", "s": "math", "t": "prob", "k": "comb.perm", "d": 2, "est": 90, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Үш кітапты сөреге қатар қоюдың неше түрлі реті бар?", "ru": "Сколькими способами можно поставить три книги на полку в ряд?"}, "a": {"kk": "6", "ru": "6"}, "w": [[{"kk": "3", "ru": "3"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}], [{"kk": "9", "ru": "9"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}], [{"kk": "12", "ru": "12"}, {"kk": "Қосу мен көбейтуді шатастыру; әр жейденің әр шалбармен үйлесе алатынын тексер.", "ru": "Перепутать сложение и умножение; проверь, что каждая рубашка сочетается с каждыми брюками."}]], "h": {"kk": "Екі тәуелсіз таңдау болса, бірінші нұсқалардың санын екінші нұсқалардың санына көбейт. Жұпты реті маңызды емес таңдауда екі рет санап қойма.", "ru": "При двух независимых выборах число вариантов первого умножают на число вариантов второго. Если порядок не важен, не считай пару дважды."}, "e": {"kk": "Бірінші орынға 3, екіншіге 2, соңғысына 1 таңдау: 3×2×1=6.", "ru": "На первое место 3 варианта, на второе 2, на последнее 1: 3 × 2 × 1 = 6."}});
  add({"id": "nis6-logic-087", "s": "math", "t": "logic", "k": "logic.compare", "d": 3, "est": 120, "src": "pack1", "pool": "logic"}, {"q": {"kk": "Ойлаған сан 4-ке бөлгенде қалдық 1 береді және 20-дан кіші. Төмендегі сандардың қайсысы сәйкес келеді?", "ru": "Задуманное число при делении на 4 даёт остаток 1 и меньше 20. Какое из чисел подходит?"}, "a": {"kk": "17", "ru": "17"}, "w": [[{"kk": "16", "ru": "16"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}], [{"kk": "18", "ru": "18"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}], [{"kk": "19", "ru": "19"}, {"kk": "Шекаралық санды қосып жіберу немесе қажетті санды ұмыту.", "ru": "Включить граничное число или пропустить нужное."}]], "h": {"kk": "Шартқа сай келетін барлық санды тізіп шық.", "ru": "Выпиши все числа, подходящие под условие."}, "e": {"kk": "17 = 4×4+1. Қалған нұсқалар 4-ке бөлгенде 1 қалдық бермейді.", "ru": "17 = 4 × 4 + 1. Остальные числа при делении на 4 не дают остаток 1."}});
  add({"id": "nis6-english-088", "s": "en", "t": "enmini", "k": "en.grammar", "d": 2, "est": 90, "src": "pack1", "lv": 2}, {"fixed": "en", "q": "Choose the correct word: Last night, I ___ a letter to my cousin.", "a": "wrote", "w": [["write", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["writes", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["am writing", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}]], "h": {"kk": "Әдеттегі іс үшін Present Simple; yesterday сияқты өткен уақыт белгісімен Past Simple. He/she/it тұлғасында етістікке -s/-es жалғанады.", "ru": "Present Simple — для привычных действий; с yesterday — Past Simple. С he/she/it к глаголу добавляется -s/-es."}, "e": {"kk": "Last night өткен уақытты көрсетеді. write етістігінің Past Simple түрі — wrote.", "ru": "Last night указывает на прошлое. Past Simple от write — wrote."}});
  add({"id": "nis6-english-089", "s": "en", "t": "enmini", "k": "en.grammar", "d": 2, "est": 90, "src": "pack1", "lv": 2}, {"fixed": "en", "q": "Look! The children ___ in the garden.", "a": "are playing", "w": [["play", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["plays", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["played", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}]], "h": {"kk": "Әдеттегі іс үшін Present Simple; yesterday сияқты өткен уақыт белгісімен Past Simple. He/she/it тұлғасында етістікке -s/-es жалғанады.", "ru": "Present Simple — для привычных действий; с yesterday — Past Simple. С he/she/it к глаголу добавляется -s/-es."}, "e": {"kk": "Look! әрекеттің дәл қазір болып жатқанын білдіреді: are + verb-ing.", "ru": "Look! показывает, что действие происходит прямо сейчас: are + глагол с -ing."}});
  add({"id": "nis6-english-090", "s": "en", "t": "enmini", "k": "en.grammar", "d": 2, "est": 90, "src": "pack1", "lv": 2}, {"fixed": "en", "q": "How ___ apples are in the basket?", "a": "many", "w": [["much", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["a little", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["any of", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}]], "h": {"kk": "Әдеттегі іс үшін Present Simple; yesterday сияқты өткен уақыт белгісімен Past Simple. He/she/it тұлғасында етістікке -s/-es жалғанады.", "ru": "Present Simple — для привычных действий; с yesterday — Past Simple. С he/she/it к глаголу добавляется -s/-es."}, "e": {"kk": "Apples саналатын көпше зат есім, сондықтан many қолданылады.", "ru": "Apples — исчисляемое существительное во множественном числе, поэтому many."}});
  add({"id": "nis6-english-091", "s": "en", "t": "enmini", "k": "en.vocab", "d": 2, "est": 90, "src": "pack1", "lv": 2}, {"fixed": "en", "q": "The instructions were clear, so everyone knew what to do. What does “clear” mean here?", "a": "Easy to understand", "w": [["Very expensive", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["Difficult to see", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["Full of water", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}]], "h": {"kk": "Алдымен сұрақты оқы. Мәтіндегі тірек сөзді тап.", "ru": "Сначала прочитай вопрос. Найди в тексте ключевое слово. Проверь, что текст подтверждает ответ."}, "e": {"kk": "Нұсқаулар түсінікті болғаны үшін бәрі не істеу керегін білді.", "ru": "Инструкции были понятными, поэтому все знали, что делать: clear = easy to understand."}});
  add({"id": "nis6-english-092", "s": "en", "t": "enmini", "k": "en.read", "d": 2, "est": 90, "src": "pack1", "lv": 2}, {"fixed": "en", "q": "Read: “First, Leo washed the apples. Then he cut them. Finally, he put them in a bowl.” What did Leo do after washing the apples?", "a": "He cut them.", "w": [["He bought a bowl.", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["He ate them.", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["He washed the bowl.", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}]], "h": {"kk": "Алдымен сұрақты оқы. Мәтіндегі тірек сөзді тап.", "ru": "Сначала прочитай вопрос. Найди в тексте ключевое слово. Проверь, что текст подтверждает ответ."}, "e": {"kk": "Then сөзі келесі әрекетті көрсетеді: алма жуды, содан кейін кесті.", "ru": "Then показывает следующее действие: сначала помыл яблоки, потом нарезал."}});
  add({"id": "nis6-english-093", "s": "en", "t": "enmini", "k": "en.grammar", "d": 1, "est": 60, "src": "pack1", "lv": 1}, {"fixed": "en", "q": "Choose the correct there is/are sentence.", "a": "There are three books on the desk.", "w": [["There is three books on the desk.", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["There are a book on the desk.", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["There be three books on the desk.", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}]], "h": {"kk": "Әдеттегі іс үшін Present Simple; yesterday сияқты өткен уақыт белгісімен Past Simple. He/she/it тұлғасында етістікке -s/-es жалғанады.", "ru": "Present Simple — для привычных действий; с yesterday — Past Simple. С he/she/it к глаголу добавляется -s/-es."}, "e": {"kk": "Үш кітап — көпше түр, сондықтан there are қолданылады.", "ru": "Три книги — множественное число, поэтому there are."}});
  add({"id": "nis6-english-094", "s": "en", "t": "enmini", "k": "en.vocab", "d": 1, "est": 60, "src": "pack1", "lv": 1}, {"fixed": "en", "q": "What is the opposite of “careful”?", "a": "Careless", "w": [["Helpful", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["Quiet", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}], ["Patient", {"kk": "Өз біліміңе сүйеніп, мәтінде айтылмаған ақпаратты қосу.", "ru": "Добавлять сведения, которых нет в тексте."}]], "h": {"kk": "Алдымен сұрақты оқы. Мәтіндегі тірек сөзді тап.", "ru": "Сначала прочитай вопрос. Найди в тексте ключевое слово. Проверь, что текст подтверждает ответ."}, "e": {"kk": "Careless — ұқыпсыз; careful сөзінің қарама-қарсы мағынасы.", "ru": "Careless — небрежный; это противоположность careful."}});
  add({"id": "nis6-english-095", "s": "en", "t": "enmini", "k": "en.grammar", "d": 2, "est": 120, "src": "pack1", "lv": 2}, {"fixed": "en", "q": "Maya and I finished the project. Our teacher praised ___.", "a": "us", "w": [["we", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["our", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}], ["ours", {"kk": "Уақыт белгісін байқамау немесе he/she/it тұлғасында -s жалғауын ұмыту.", "ru": "Не заметить слово-сигнал времени или забыть -s с he/she/it."}]], "h": {"kk": "Әдеттегі іс үшін Present Simple; yesterday сияқты өткен уақыт белгісімен Past Simple. He/she/it тұлғасында етістікке -s/-es жалғанады.", "ru": "Present Simple — для привычных действий; с yesterday — Past Simple. С he/she/it к глаголу добавляется -s/-es."}, "e": {"kk": "Praised етістігінен кейін толықтауыш керек; I and Maya үшін object pronoun — us.", "ru": "После praised нужно дополнение; для Maya and I объектное местоимение — us."}});
  add({"id": "nis6-science-096", "s": "sci", "t": "sbio", "k": "sci.ecology", "d": 1, "est": 60, "src": "pack1"}, {"q": {"kk": "Қоректік тізбекте қай ағза өндіруші болады: шөп → шегіртке → бақа?", "ru": "Какой организм в пищевой цепи трава → кузнечик → лягушка является производителем?"}, "a": {"kk": "Шөп", "ru": "Трава"}, "w": [[{"kk": "Шегіртке", "ru": "Кузнечик"}, {"kk": "Жебені «кім кімді жейді» бағытымен шатастыру; жебе энергияның берілу бағытын көрсетеді.", "ru": "Перепутать направление стрелки: она показывает, куда передаётся энергия."}], [{"kk": "Бақа", "ru": "Лягушка"}, {"kk": "Жебені «кім кімді жейді» бағытымен шатастыру; жебе энергияның берілу бағытын көрсетеді.", "ru": "Перепутать направление стрелки: она показывает, куда передаётся энергия."}], [{"kk": "Барлығы", "ru": "Все"}, {"kk": "Жебені «кім кімді жейді» бағытымен шатастыру; жебе энергияның берілу бағытын көрсетеді.", "ru": "Перепутать направление стрелки: она показывает, куда передаётся энергия."}]], "h": {"kk": "Өсімдіктер күн энергиясын пайдаланып органикалық зат түзеді. Жануарлар басқа ағзалармен қоректенетін тұтынушылар.", "ru": "Растения создают органические вещества за счёт энергии Солнца. Животные — потребители. Стрелка показывает передачу энергии."}, "e": {"kk": "Шөп күн энергиясын пайдаланып өз қорегін түзеді, сондықтан өндіруші.", "ru": "Трава сама создаёт себе питание, используя энергию Солнца, поэтому она — производитель."}});
  add({"id": "nis6-science-097", "s": "sci", "t": "sexp", "k": "sci.method", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Тұқымға судың әсерін тексергенде қандай шарттарды бірдей ұстаған дұрыс?", "ru": "Какие условия нужно оставить одинаковыми, проверяя влияние воды на семена?"}, "a": {"kk": "Тұқым түрін, жарық пен топырақты", "ru": "Вид семян, свет и почву"}, "w": [[{"kk": "Судың мөлшерін және тұқым түрін", "ru": "Количество воды и вид семян"}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}], [{"kk": "Тек өсімдіктің түсін", "ru": "Только цвет растения"}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}], [{"kk": "Барлық шартты өзгерту", "ru": "Изменить все условия"}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}]], "h": {"kk": "Бір ғана факторды әдейі өзгерт. Қалған маңызды шарттарды бірдей ұста.", "ru": "Намеренно меняй только один фактор. Остальные важные условия держи одинаковыми. Вывод делай только по данным."}, "e": {"kk": "Судың әсерін бөлек тексеру үшін басқа маңызды шарттар бірдей болуы керек.", "ru": "Чтобы проверить влияние воды отдельно, остальные важные условия должны быть одинаковыми."}});
  add({"id": "nis6-science-098", "s": "sci", "t": "sgeo", "k": "sci.earth", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Күннің шығуы мен батуы күн сайын қай құбылыспен түсіндіріледі?", "ru": "Каким явлением объясняется ежедневный восход и заход Солнца?"}, "a": {"kk": "Жердің өз осінен айналуымен", "ru": "Вращением Земли вокруг своей оси"}, "w": [[{"kk": "Айдың Жерді айналуымен", "ru": "Вращением Луны вокруг Земли"}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}], [{"kk": "Күннің Жерді айналуымен", "ru": "Вращением Солнца вокруг Земли"}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}], [{"kk": "Бұлттардың қозғалуымен", "ru": "Движением облаков"}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}]], "h": {"kk": "Құбылыстың себебі мен нәтижесін ажырат.", "ru": "Отдели причину явления от результата."}, "e": {"kk": "Жердің өз осінен айналуы күн мен түннің алмасуын туғызады.", "ru": "Вращение Земли вокруг своей оси вызывает смену дня и ночи."}});
  add({"id": "nis6-science-099", "s": "sci", "t": "schem", "k": "sci.mixtures", "d": 2, "est": 90, "src": "pack1"}, {"q": {"kk": "Құм мен судың қоспасын ажыратуға қай әдіс қолайлы?", "ru": "Каким способом удобно разделить смесь песка и воды?"}, "a": {"kk": "Сүзу", "ru": "Фильтрованием"}, "w": [[{"kk": "Мұздату", "ru": "Замораживанием"}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}], [{"kk": "Магнитпен тарту", "ru": "Притягиванием магнитом"}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}], [{"kk": "Араластыру", "ru": "Перемешиванием"}, {"kk": "Бақылауды «жоғалып кетті» немесе «өздігінен болды» деп түсіндіру.", "ru": "Объяснять наблюдение словами «исчезло» или «само собой»."}]], "h": {"kk": "Құбылыстың себебі мен нәтижесін ажырат.", "ru": "Отдели причину явления от результата."}, "e": {"kk": "Құм суда ерімейді; сүзгі құмды ұстап, суды өткізе алады.", "ru": "Песок не растворяется в воде; фильтр задерживает песок и пропускает воду."}});
  add({"id": "nis6-science-100", "s": "sci", "t": "sphys", "k": "sci.light", "d": 1, "est": 60, "src": "pack1"}, {"q": {"kk": "Мөлдір емес зат жарық көзі мен қабырға арасында тұр. Қабырғада не пайда болады?", "ru": "Непрозрачный предмет стоит между источником света и стеной. Что появится на стене?"}, "a": {"kk": "Көлеңке", "ru": "Тень"}, "w": [[{"kk": "Радуга", "ru": "Радуга"}, {"kk": "Бақыланған өзгерістен артық қорытынды жасау.", "ru": "Делать слишком широкий вывод из одного наблюдения."}], [{"kk": "Дыбыс толқыны", "ru": "Звуковая волна"}, {"kk": "Бақыланған өзгерістен артық қорытынды жасау.", "ru": "Делать слишком широкий вывод из одного наблюдения."}], [{"kk": "Жаңа жарық көзі", "ru": "Новый источник света"}, {"kk": "Бақыланған өзгерістен артық қорытынды жасау.", "ru": "Делать слишком широкий вывод из одного наблюдения."}]], "h": {"kk": "Жылу жылырақ денеден салқынырақ денеге беріледі. Металл жылуды жақсы өткізеді.", "ru": "Тепло передаётся от более тёплого тела к более холодному. Металл хорошо проводит тепло."}, "e": {"kk": "Мөлдір емес зат жарықты өткізбейді, сондықтан оның артында көлеңке пайда болады.", "ru": "Непрозрачный предмет не пропускает свет, поэтому за ним появляется тень."}});
  add({"id": "nis6-science-101", "s": "sci", "t": "sexp", "k": "sci.method", "d": 3, "est": 120, "src": "pack1"}, {"q": {"kk": "Екі қағаз ұшақтың ұшу қашықтығын салыстырғанда, нәтижені қалай сенімдірек етуге болады?", "ru": "Как сделать результат надёжнее, сравнивая дальность полёта двух бумажных самолётиков?"}, "a": {"kk": "Әр ұшақты бірнеше рет бірдей жағдайда ұшырып, орташа қашықтықты салыстыру.", "ru": "Запустить каждый самолётик несколько раз в одинаковых условиях и сравнить среднюю дальность."}, "w": [[{"kk": "Әр ұшақты бір рет әр жерде ұшыру.", "ru": "Запустить каждый по одному разу в разных местах."}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}], [{"kk": "Ең жақсы нәтижені ғана жазу.", "ru": "Записать только лучший результат."}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}], [{"kk": "Ұшақтың түсіне қарап таңдау.", "ru": "Выбрать по цвету самолётика."}, {"kk": "Бір уақытта бірнеше шартты өзгертіп, қайсысы әсер еткенін біле алмау.", "ru": "Изменить сразу несколько условий и не понять, какое из них повлияло."}]], "h": {"kk": "Бір ғана факторды әдейі өзгерт. Қалған маңызды шарттарды бірдей ұста.", "ru": "Намеренно меняй только один фактор. Остальные важные условия держи одинаковыми. Вывод делай только по данным."}, "e": {"kk": "Қайталау кездейсоқ айырмаларды азайтады; бірдей жағдайлар салыстыруды әділ етеді.", "ru": "Повторы уменьшают случайные различия, а одинаковые условия делают сравнение честным."}});
  add({"id": "nis6-kk-102", "s": "kk", "t": "kkmini", "k": "kk.grammar", "d": 2, "est": 90, "src": "pack1"}, {"fixed": "kk", "q": "«Бала кітапты асықпай оқыды» сөйлемінде «асықпай» сөзі қимылдың қалай орындалғанын білдіреді. Қай сұраққа жауап береді?", "a": "Қалай?", "w": [["Кім?", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."], ["Нені?", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."], ["Қашан?", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."]], "h": "Сөзге сұрақ қойып көр: кім? не істеді? қалай?", "e": "Асықпай сөзі оқудың қалай орындалғанын көрсетеді, сондықтан «қалай?» сұрағына жауап береді."});
  add({"id": "nis6-kk-103", "s": "kk", "t": "kkmini", "k": "kk.read", "d": 3, "est": 120, "src": "pack1"}, {"fixed": "kk", "q": "Мәтін: «Ержан жаттығуға бөтелкесін толтырып әкелді. Жаттығудан кейін бөтелкеде су қалмады». Қай қорытынды мәтінге ең жақын?", "a": "Ержан жаттығу кезінде су ішкен болуы мүмкін.", "w": [["Ержан суды түгел төгіп алды.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."], ["Бөтелке сынған.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."], ["Жаттығу төрт сағатқа созылды.", "Өзің білетін ақпаратты мәтіннің нақты дерегі ретінде қабылдау."]], "h": "Негізгі ой бірнеше сөйлемді біріктіреді. Тікелей дерек мәтінде нақты айтылады.", "e": "Судың жаттығудан кейін қалмауы ішкен болуы мүмкін деген қорытындыға негіз болады, бірақ нақты себеп белгісіз."});
  add({"id": "nis6-kk-104", "s": "kk", "t": "kkmini", "k": "kk.grammar", "d": 1, "est": 60, "src": "pack1"}, {"fixed": "kk", "q": "«Достарымыз» сөзінің түбірі қайсы?", "a": "дос", "w": [["достар", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."], ["тар", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."], ["ымыз", "Сұрақты дұрыс қоймай, сөз табын немесе сөйлем мүшесін шатастыру."]], "h": "Сөзге сұрақ қойып көр: кім? не істеді? қалай?", "e": "Сөздің негізгі мағынасы «дос» түбірінде сақталған; қалған бөліктер — қосымшалар."});
